mapper.select:
select A.FINPROD_ID, T1.FINPROD_MARKET_ID assetId, nvl(T1.FINPROD_ABBR, t1.FINPROD_NAME) assetName, T7.TYPE_6 assetType, to_char(A.EFF_DATE, 'yyyy-MM-dd') EFF_DATE, A.BUYOUT_RATE*100 RATE
from PA_FIN_PRODUCT_BUYOUT_RATE A
LEFT JOIN FIN_PRODUCT T1 ON A.FINPROD_ID = T1.FINPROD_ID AND T1.FINPROD_TYPE2=#{FINPROD_TYPE_TG_F18}
LEFT JOIN FIN_PRODUCT_TYPE T7 on T7.FINPROD_ID = T1.FINPROD_ID

    T1.FINPROD_MARKET_ID is not null

        #{item}


        #{item}


        and A.EFF_DATE = to_date(#{effDate}, 'yyyy-MM-dd')


ORDER BY A.EFF_DATE DESC

select T1.FINPROD_MARKET_ID id, NVL(T1.FINPROD_ABBR, T1.FINPROD_NAME) text, nvl(T1.FINPROD_ABBR, t1.FINPROD_NAME) object, T1.FINPROD_ID col, T2.TYPE_6 parentId
from FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 on T2.FINPROD_ID = T1.FINPROD_ID
where FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F18}

    and (instr(T1.FINPROD_MARKET_ID, #{search}) > 0 or instr(T1.FINPROD_ABBR, #{search}) > 0 or instr(T1.FINPROD_NAME, #{search}) > 0)


    and T2.TYPE_6 = #{assetType}

SELECT COUNT(1) FROM PA_FIN_PRODUCT_BUYOUT_RATE
WHERE FINPROD_ID = #{finprodId}
AND EFF_DATE = to_date(#{effDate}, 'yyyy-MM-dd')
